$id=(int)($_GET['id']??$_POST['id']??0);$stmt=$db->prepare('SELECT a.*,s.name status_name,s.display_color status_color,f.title form_title FROM applications a LEFT JOIN statuses s ON s.id=a.current_status_id LEFT JOIN forms f ON f.id=a.form_id WHERE a.id=? LIMIT 1');$stmt->execute([$id]);$app=$stmt->fetch();if(!$app){http_response_code(404);exit('Application not found.');}
if($_SERVER['REQUEST_METHOD']==='POST'){
