   if(!$title){flash('error','Update title is required.');redirect('gadmin8f3k2p9x7m4q6v1c/application.php?id='.$id);}if($linkUrl!==''&&!safe_return_url($linkUrl)){flash('error','Links must use a valid https:// URL.');redirect('gadmin8f3k2p9x7m4q6v1c/application.php?id='.$id);}
   $db->beginTransaction();try{$statusName=null;$statusColor=null;if($statusId){$ss=$db->prepare('SELECT name,display_color FROM statuses WHERE id=?');$ss->execute([$statusId]);$sr=$ss->fetch();if($sr){$statusName=$sr['name'];$statusColor=$sr['display_color'];}else{$statusId=0;}}$ins=$db->prepare("INSERT INTO application_updates(application_id,status_id,status_name_snapshot,status_color_snapshot,actor_type,title,message,link_label,link_url) VALUES (?,?,?,?,'admin',?,?,?,?)");$ins->execute([$id,$statusId?:null,$statusName,$statusColor,$title,$message,$linkLabel?:null,$linkUrl?:null]);if($statusId){$db->prepare('UPDATE applications SET current_status_id=? WHERE id=?')->execute([$statusId,$id]);}$db->commit();$emailSent=send_update_email($app,['title'=>$title,'message'=>$message,'link_label'=>$linkLabel,'link_url'=>$linkUrl]);flash($emailSent?'success':'error',$emailSent?'Application update saved and email notification sent.':'Application update saved, but the email could not be sent. '.mail_last_error());}catch(Throwable $e){if($db->inTransaction())$db->rollBack();flash('error','Could not save update.');}redirect('gadmin8f3k2p9x7m4q6v1c/application.php?id='.$id);
 }
 if($action==='resend_confirmation'){$ok=send_application_confirmation($app);flash($ok?'success':'error',$ok?'Confirmation email sent successfully.':'Confirmation email could not be sent. '.mail_last_error());redirect('gadmin8f3k2p9x7m4q6v1c/application.php?id='.$id);}
 if($action==='toggle_archive'){$new=$app['is_archived']?0:1;$db->prepare('UPDATE applications SET is_archived=? WHERE id=?')->execute([$new,$id]);flash('success',$new?'Application archived.':'Application restored.');redirect('gadmin8f3k2p9x7m4q6v1c/application.php?id='.$id);}
 if($action==='delete'){$files=$db->prepare('SELECT stored_name FROM application_files WHERE application_id=?');$files->execute([$id]);foreach($files->fetchAll() as $f){$p=UPLOAD_PATH.'/'.$f['stored_name'];if(is_file($p))@unlink($p);}$db->prepare('DELETE FROM applications WHERE id=?')->execute([$id]);flash('success','Application permanently deleted.');redirect('gadmin8f3k2p9x7m4q6v1c/applications.php');}
}
$statuses=$db->query('SELECT * FROM statuses ORDER BY name')->fetchAll();$updates=$db->prepare('SELECT u.*,COALESCE(u.status_name_snapshot,s.name) status_name,COALESCE(u.status_color_snapshot,s.display_color) status_color FROM application_updates u LEFT JOIN statuses s ON s.id=u.status_id WHERE u.application_id=? ORDER BY u.created_at DESC,u.id DESC');$updates->execute([$id]);$updates=$updates->fetchAll();$files=$db->prepare('SELECT * FROM application_files WHERE application_id=? ORDER BY created_at');$files->execute([$id]);$allFiles=$files->fetchAll();$filesByUpdate=[];$initialFiles=[];foreach($allFiles as $f){if($f['update_id'])$filesByUpdate[$f['update_id']][]=$f;else $initialFiles[]=$f;}$answers=json_decode($app['answers_json'],true)?:[];$snapshot=json_decode($app['form_snapshot_json'],true)?:[];$labels=[];foreach($snapshot['fields']??[] as $f)$labels[$f['field_key']]=$f['label'];
$adminTitle='Application '.$app['tracking_code'];require __DIR__.'/_header.php';
