<div class="panel"><div class="panel-head"><div><a href="applications.php">← Applications</a><h2 style="margin:8px 0 0"><?=h($app['full_name'])?></h2><div class="code"><?=h($app['tracking_code'])?></div></div><div class="actions"><?php if($app['status_name']):?><span class="badge" style="background:<?=h($app['status_color'])?>"><?=h($app['status_name'])?></span><?php else:?><span class="muted">No status</span><?php endif;?></div></div><div class="answer-grid"><div class="answer"><b>Email</b><a href="mailto:<?=h($app['email'])?>"><?=h($app['email'])?></a></div><div class="answer"><b>Location</b><?=h(location_label($app['location']))?></div><div class="answer"><b>Application form</b><?=h($app['form_title']?:($snapshot['title']??'Deleted form'))?> · v<?= (int)$app['form_version']?></div><div class="answer"><b>Submitted</b><?=h(date('F j, Y · g:i A',strtotime($app['created_at'])))?></div></div></div>
